/**
 * The BMP code points that the legacy exporter's encoder
 * (`JavaScriptEncoder.UnsafeRelaxedJsonEscaping` on .NET 10) writes as `\uXXXX` escapes:
 * controls, `"`, backslash, unassigned and private-use code points and a few others.
 * Generated by probing every code point with the legacy-final runtime (see the
 * transfer fixtures README). Each entry is `gap+length` in hexadecimal: the start
 * is the previous range's end plus the gap, and the range covers `length + 1` points.
 */
const ENCODED_RANGES = [
  "0+1f 3+0 3a+0 23+21 2d8+1 7+3 8+0 2+0 15+0 18e+0 27+1 33+1 4+0 38+7 1c+3 7+a 10f+0 3d+1 ",
  "66+d 3c+1 32+1 10+0 1d+1 2+0 c+4 20+0 3+4 ee+0 9+1 3+1 17+0 8+0 2+2 5+1 a+1 3+1 5+7 2+3 ",
  "3+0 6+1 1a+1 4+0 7+3 3+1 17+0 8+0 3+0 3+0 3+1 2+0 6+3 3+1 4+2 2+6 5+0 2+6 12+9 4+0 a+0 ",
  "4+0 17+0 8+0 3+0 6+1 b+0 4+0 4+1 2+e 5+1 d+6 8+0 4+0 9+1 3+1 17+0 8+0 3+0 6+1 a+1 3+1 ",
  "4+6 4+3 3+0 6+1 13+9 3+0 7+2 4+0 5+2 3+0 2+0 3+2 3+2 4+2 d+3 6+2 4+0 5+1 2+5 2+d 16+4 ",
  "e+0 4+0 18+0 11+1 a+0 4+0 5+6 3+0 4+1 2+1 5+1 b+6 17+0 4+0 18+0 b+0 6+1 a+0 4+0 5+6 3+5 ",
  "3+0 5+1 b+0 4+b e+0 4+0 34+0 4+0 7+3 11+1 1b+0 4+0 13+2 19+0 a+0 2+1 8+2 2+3 7+0 2+0 9+5 ",
  "b+1 4+b 3b+3 1e+24 3+0 2+0 6+0 19+0 2+0 18+1 6+0 2+0 8+0 b+1 5+1f 49+0 25+3 28+0 25+0 ",
  "10+0 e+24 c7+0 2+4 2+1 17a+0 5+1 8+0 2+0 5+1 2a+0 5+1 22+0 5+1 8+0 2+0 5+1 10+0 3a+0 5+1 ",
  "44+1 21+2 1b+5 57+1 7+1 281+0 1d+2 5a+6 17+8 19+8 15+b e+0 4+0 3+b 5f+1 b+5 b+5 1b+5 ",
  "5a+6 2c+4 47+9 20+0 d+3 d+3 2+2 2b+1 6+a 2d+3 1b+5 c+2 3f+1 42+0 1e+1 c+5 b+5 f+1 20+30 ",
  "4e+0 a7+7 3d+2 10+2 3f+4 2c+1 c+7 2c+4 217+1 7+1 27+1 7+1 9+0 2+0 2+0 2+0 20+1 36+0 10+0 ",
  "f+1 7+0 14+1 4+0 a+b 1e+1 6+0 30+0 6+0 d+1 1c+0 e+2 22+e 22+e 8d+3 29b+15 c+14 715+1 ",
  "21+0 15e+4 2e+0 2+4 2+1 39+6 3+d 19+8 8+0 8+0 8+0 8+0 8+0 8+0 8+0 8+0 7f+21 1b+0 5a+b ",
  "d7+19 11+0 40+0 57+1 68+4 2c+0 5f+0 57+8 31+0 726e+2 38+8 15d+13 b9+7 cf+1 3+0 2+0 9+14 ",
  "3c+2 b+5 39+7 47+7 d+5 75+a 1f+2 4f+0 c+3 22+0 38+8 f+1 b+1 68+17 1d+9 7+1 7+1 7+8 8+0 ",
  "8+0 3d+3 7f+1 b+5 2ba5+b 18+3 32+2103 16f+1 6b+25 8+b 6+4 1b+0 6+0 2+0 3+0 3+0 7e+f ",
  "1be+1 37+6 2+1f 2b+5 34+0 14+0 5+3 6+0 88+3 bf+2 7+1 7+1 7+1 4+2 8+0 8+9 6+1 ",
].join("");

function decodeRanges(text: string): ReadonlyArray<readonly [number, number]> {
  let end = 0;
  return text
    .trim()
    .split(/\s+/)
    .map((entry) => {
      const [gap, length] = entry.split("+").map((part) => Number.parseInt(part, 16));
      const start = end + gap!;
      end = start + length!;
      return [start, end] as const;
    });
}

/** Inclusive `[first, last]` ranges of escaped BMP code points, in ascending order. */
export const STJ_ESCAPED_RANGES = decodeRanges(ENCODED_RANGES);
